    ("People believe that the ancient artifact was smuggled out of Egypt.", "THOUGHT", "The ancient artifact ______________________________ smuggled out of Egypt.", ["is thought to have been"], "Pasivní reporting s minulým časem: 'is thought to have been smuggled'.", "is said/thought TO HAVE BEEN + V3."),
    ("If it hadn't been for your generous donation, the shelter would have closed.", "BUT", "______________________________ generous donation, the shelter would have closed.", ["but for your", "But for your"], "'But for + noun' nahrazuje 3. kondicionál ('Kdyby nebylo...').", "But for your help = Had it not been for your help."),
    ("I really regret not accepting the scholarship when I was twenty.", "WISH", "I really ______________________________ the scholarship when I was twenty.", ["wish i had accepted", "wish I had accepted"], "Lítost nad minulostí vyjadřuje vazba 'wish + past perfect'.", "I wish I had done it = Kéž bych to býval udělal."),
    ("Under no circumstances should visitors touch the exhibits.", "ACCOUNT", "On ______________________________ touch the exhibits.", ["no account should visitors", "no account must visitors"], "'On no account' spouští zápornou inverzi: 'should visitors touch'.", "On no account + pomocné sloveso + podmět."),
    ("It is impossible that Sarah took the car keys because she was with me.", "HAVE", "Sarah ______________________________ the car keys because she was with me.", ["could not have taken", "cannot have taken", "couldn't have taken", "can't have taken"], "Záporná dedukce v minulosti: nemohla to vzít = could not have taken.", "Can't have done / Couldn't have done."),
